WITH recent_store_sales AS (SELECT *, DATE_FORMAT(sale_date, 'MMM yyyy') AS sale_date_label FROM store_sales WHERE product_id = 9), sale_month_summary AS (SELECT MONTH(sale_date) AS sale_month, store_id, COUNT(DISTINCT units) AS unique_products FROM recent_store_sales GROUP BY MONTH(sale_date), store_id) SELECT sale_month, store_id, unique_products FROM sale_month_summary ORDER BY store_id
